CREATE TABLE rw0_evidence_values (
  "schema_id" ANY NOT NULL CHECK (typeof("schema_id")='text' AND "schema_id"='governed-execution.nwp-rw0-c1-evidence-value-row.v1'),
  "kind_rank" ANY NOT NULL CHECK (typeof("kind_rank")='integer' AND "kind_rank" BETWEEN 0 AND 9223372036854775807),
  "value_ref" ANY NOT NULL CHECK (typeof("value_ref")='text' AND length(CAST("value_ref" AS BLOB))=length("value_ref") AND length(CAST("value_ref" AS BLOB)) BETWEEN 1 AND 96 AND "value_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("value_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("value_ref") NOT GLOB 'connector-*' AND lower("value_ref") NOT GLOB 'tunnel-*' AND lower("value_ref") NOT GLOB 'workspace-*' AND lower("value_ref") NOT GLOB 'org-*' AND lower("value_ref") NOT GLOB 'organization-*' AND lower("value_ref") NOT GLOB 'user-*'),
  "value_digest" ANY NOT NULL CHECK (typeof("value_digest")='text' AND length(CAST("value_digest" AS BLOB))=64 AND "value_digest" NOT GLOB '*[^0-9a-f]*'),
  "value_schema_id" ANY NOT NULL CHECK (typeof("value_schema_id")='text' AND length(CAST("value_schema_id" AS BLOB)) BETWEEN 1 AND 256),
  "scope_class" ANY NOT NULL CHECK (typeof("scope_class")='text' AND length(CAST("scope_class" AS BLOB)) BETWEEN 1 AND 256),
  "value_row_digest" ANY NOT NULL CHECK (typeof("value_row_digest")='text' AND length(CAST("value_row_digest" AS BLOB))=64 AND "value_row_digest" NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (kind_rank, value_ref),
  UNIQUE (kind_rank, value_digest),
  UNIQUE (kind_rank, value_ref, value_digest, value_schema_id),
  CHECK (kind_rank BETWEEN 1 AND 15),
  CHECK (scope_class IN ('global_reusable','phase_bound','k8_bound','existing_owner_row_bound')),
  CHECK (
    (kind_rank=1 AND value_schema_id='governed-execution.nwp-rw0-authority-verification-observation.v1' AND scope_class='phase_bound') OR
    (kind_rank=2 AND value_schema_id='governed-execution.nwp-rw0-subordinate-authorization-proposal.v1' AND scope_class='phase_bound') OR
    (kind_rank=3 AND value_schema_id='governed-execution.nwp-rw0-custody-availability-observation.v1' AND scope_class='phase_bound') OR
    (kind_rank=4 AND value_schema_id='governed-execution.nwp-rw0-retrieval-capability-event-observation.v1' AND scope_class='phase_bound') OR
    (kind_rank=5 AND value_schema_id='governed-execution.nwp-rw0-remote-host-readiness-observation.v1' AND scope_class='global_reusable') OR
    (kind_rank=6 AND value_schema_id='governed-execution.nwp-rw0-effect-host-qualification.v1' AND scope_class='phase_bound') OR
    (kind_rank=7 AND value_schema_id='governed-execution.nwp-rw0-worker-mechanism-capability-declaration.v1' AND scope_class='global_reusable') OR
    (kind_rank=8 AND value_schema_id='governed-execution.nwp-rw0-worker-mechanism-capability-observation.v1' AND scope_class='global_reusable') OR
    (kind_rank=9 AND value_schema_id='governed-execution.nwp-rw0-worker-mechanism-capability-qualification.v1' AND scope_class='phase_bound') OR
    (kind_rank=10 AND value_schema_id='governed-execution.nwp-rw0-wire-cancellation-request-observation.v1' AND scope_class='k8_bound') OR
    (kind_rank=11 AND value_schema_id='governed-execution.nwp-rw0-wire-process-observation.v1' AND scope_class='k8_bound') OR
    (kind_rank=12 AND value_schema_id='governed-execution.nwp-worker-observation.v1' AND scope_class='k8_bound') OR
    (kind_rank=13 AND value_schema_id='governed-execution.nwp-rw0-c1-wire-worker-result-binding.v1' AND scope_class='k8_bound') OR
    (kind_rank=14 AND value_schema_id='governed-execution.nwp-rw0-c1-wire-process-result-classification-binding.v1' AND scope_class='k8_bound') OR
    (kind_rank=15 AND value_schema_id='governed-execution.nwp-rw0-c1-section41-post-execution-proposal-family-member.v1' AND scope_class='existing_owner_row_bound')
  )
) STRICT;

