  "relation_ref" ANY NOT NULL CHECK (typeof("relation_ref")='text' AND length(CAST("relation_ref" AS BLOB))=length("relation_ref") AND length(CAST("relation_ref" AS BLOB)) BETWEEN 1 AND 96 AND "relation_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("relation_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("relation_ref") NOT GLOB 'connector-*' AND lower("relation_ref") NOT GLOB 'tunnel-*' AND lower("relation_ref") NOT GLOB 'workspace-*' AND lower("relation_ref") NOT GLOB 'org-*' AND lower("relation_ref") NOT GLOB 'organization-*' AND lower("relation_ref") NOT GLOB 'user-*'),
