  "operand_ordinal" ANY NOT NULL CHECK (typeof("operand_ordinal")='integer' AND "operand_ordinal" BETWEEN 0 AND 9223372036854775807),
  "operand_role" ANY NOT NULL CHECK (typeof("operand_role")='text' AND length(CAST("operand_role" AS BLOB)) BETWEEN 1 AND 256),
  "operand_source" ANY NOT NULL CHECK (typeof("operand_source")='text' AND length(CAST("operand_source" AS BLOB)) BETWEEN 1 AND 256),
  "source_membership_ref" ANY CHECK ("source_membership_ref" IS NULL OR (typeof("source_membership_ref")='text' AND length(CAST("source_membership_ref" AS BLOB))=length("source_membership_ref") AND length(CAST("source_membership_ref" AS BLOB)) BETWEEN 1 AND 96 AND "source_membership_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("source_membership_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("source_membership_ref") NOT GLOB 'connector-*' AND lower("source_membership_ref") NOT GLOB 'tunnel-*' AND lower("source_membership_ref") NOT GLOB 'workspace-*' AND lower("source_membership_ref") NOT GLOB 'org-*' AND lower("source_membership_ref") NOT GLOB 'organization-*' AND lower("source_membership_ref") NOT GLOB 'user-*')),
  "source_membership_digest" ANY CHECK ("source_membership_digest" IS NULL OR (typeof("source_membership_digest")='text' AND length(CAST("source_membership_digest" AS BLOB))=64 AND "source_membership_digest" NOT GLOB '*[^0-9a-f]*')),
  "source_kind_rank" ANY CHECK ("source_kind_rank" IS NULL OR (typeof("source_kind_rank")='integer' AND "source_kind_rank" BETWEEN 1 AND 15)),
  "owner_role" ANY CHECK ("owner_role" IS NULL OR (typeof("owner_role")='text' AND "owner_role" IN ('development_work_spec_binding','development_attempt_fence','development_effect_fence','development_author_command','development_delivery_attempt','development_model_source_invocation','development_pre_execution_planning_context','development_private_proposal_artifact_binding','development_model_proposal','development_pre_execution_plan_projection','development_model_proposal_evidence_binding','development_pre_execution_disposition','development_cognitive_mutation_receipt'))),
  "owner_locator_ref" ANY CHECK ("owner_locator_ref" IS NULL OR (typeof("owner_locator_ref")='text' AND length(CAST("owner_locator_ref" AS BLOB))=length("owner_locator_ref") AND length(CAST("owner_locator_ref" AS BLOB)) BETWEEN 1 AND 96 AND "owner_locator_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("owner_locator_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("owner_locator_ref") NOT GLOB 'connector-*' AND lower("owner_locator_ref") NOT GLOB 'tunnel-*' AND lower("owner_locator_ref") NOT GLOB 'workspace-*' AND lower("owner_locator_ref") NOT GLOB 'org-*' AND lower("owner_locator_ref") NOT GLOB 'organization-*' AND lower("owner_locator_ref") NOT GLOB 'user-*')),
  "owner_locator_revision" ANY CHECK ("owner_locator_revision" IS NULL OR (typeof("owner_locator_revision")='integer' AND "owner_locator_revision" BETWEEN 0 AND 9223372036854775807)),
  "owner_locator_subrole" ANY CHECK ("owner_locator_subrole" IS NULL OR (typeof("owner_locator_subrole")='text' AND length(CAST("owner_locator_subrole" AS BLOB)) BETWEEN 1 AND 96 AND "owner_locator_subrole" GLOB '[a-z]*' AND "owner_locator_subrole" NOT GLOB '*[^a-z0-9_.-]*')),
  "owner_locator_ordinal" ANY CHECK ("owner_locator_ordinal" IS NULL OR (typeof("owner_locator_ordinal")='integer' AND "owner_locator_ordinal" BETWEEN 0 AND 9223372036854775807)),
  "transient_binding_kind" ANY CHECK ("transient_binding_kind" IS NULL OR (typeof("transient_binding_kind")='text' AND length(CAST("transient_binding_kind" AS BLOB)) BETWEEN 1 AND 256)),
  "transient_error_reason" ANY CHECK ("transient_error_reason" IS NULL OR (typeof("transient_error_reason")='text' AND length(CAST("transient_error_reason" AS BLOB)) BETWEEN 1 AND 256)),
  "snapshot_binding_kind" ANY CHECK ("snapshot_binding_kind" IS NULL OR (typeof("snapshot_binding_kind")='text' AND length(CAST("snapshot_binding_kind" AS BLOB)) BETWEEN 1 AND 256)),
  "operand_schema_id" ANY NOT NULL CHECK (typeof("operand_schema_id")='text' AND length(CAST("operand_schema_id" AS BLOB)) BETWEEN 1 AND 256),
  "operand_ref" ANY NOT NULL CHECK (typeof("operand_ref")='text' AND length(CAST("operand_ref" AS BLOB))=length("operand_ref") AND length(CAST("operand_ref" AS BLOB)) BETWEEN 1 AND 96 AND "operand_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("operand_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("operand_ref") NOT GLOB 'connector-*' AND lower("operand_ref") NOT GLOB 'tunnel-*' AND lower("operand_ref") NOT GLOB 'workspace-*' AND lower("operand_ref") NOT GLOB 'org-*' AND lower("operand_ref") NOT GLOB 'organization-*' AND lower("operand_ref") NOT GLOB 'user-*'),
  "operand_digest" ANY NOT NULL CHECK (typeof("operand_digest")='text' AND length(CAST("operand_digest" AS BLOB))=64 AND "operand_digest" NOT GLOB '*[^0-9a-f]*'),
  "operand_scope_digest" ANY CHECK ("operand_scope_digest" IS NULL OR (typeof("operand_scope_digest")='text' AND length(CAST("operand_scope_digest" AS BLOB))=64 AND "operand_scope_digest" NOT GLOB '*[^0-9a-f]*')),
  "operand_row_digest" ANY NOT NULL CHECK (typeof("operand_row_digest")='text' AND length(CAST("operand_row_digest" AS BLOB))=64 AND "operand_row_digest" NOT GLOB '*[^0-9a-f]*'),
