CREATE TABLE rw0_c1_mutation_receipts (
  "schema_id" ANY NOT NULL CHECK (typeof("schema_id")='text' AND "schema_id"='governed-execution.nwp-rw0-c1-mutation-receipt.v1'),
  "mutation_ref" ANY NOT NULL CHECK (typeof("mutation_ref")='text' AND length(CAST("mutation_ref" AS BLOB))=length("mutation_ref") AND length(CAST("mutation_ref" AS BLOB)) BETWEEN 1 AND 96 AND "mutation_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("mutation_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("mutation_ref") NOT GLOB 'connector-*' AND lower("mutation_ref") NOT GLOB 'tunnel-*' AND lower("mutation_ref") NOT GLOB 'workspace-*' AND lower("mutation_ref") NOT GLOB 'org-*' AND lower("mutation_ref") NOT GLOB 'organization-*' AND lower("mutation_ref") NOT GLOB 'user-*'),
  "mutation_family" ANY NOT NULL CHECK (typeof("mutation_family")='text' AND length(CAST("mutation_family" AS BLOB)) BETWEEN 1 AND 256),
  "command_schema_id" ANY NOT NULL CHECK (typeof("command_schema_id")='text' AND length(CAST("command_schema_id" AS BLOB)) BETWEEN 1 AND 256),
  "command_digest" ANY NOT NULL CHECK (typeof("command_digest")='text' AND length(CAST("command_digest" AS BLOB))=64 AND "command_digest" NOT GLOB '*[^0-9a-f]*'),
  "phase_basis_ref" ANY NOT NULL CHECK (typeof("phase_basis_ref")='text' AND length(CAST("phase_basis_ref" AS BLOB))=length("phase_basis_ref") AND length(CAST("phase_basis_ref" AS BLOB)) BETWEEN 1 AND 96 AND "phase_basis_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("phase_basis_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("phase_basis_ref") NOT GLOB 'connector-*' AND lower("phase_basis_ref") NOT GLOB 'tunnel-*' AND lower("phase_basis_ref") NOT GLOB 'workspace-*' AND lower("phase_basis_ref") NOT GLOB 'org-*' AND lower("phase_basis_ref") NOT GLOB 'organization-*' AND lower("phase_basis_ref") NOT GLOB 'user-*'),
  "phase_basis_digest" ANY NOT NULL CHECK (typeof("phase_basis_digest")='text' AND length(CAST("phase_basis_digest" AS BLOB))=64 AND "phase_basis_digest" NOT GLOB '*[^0-9a-f]*'),
  "membership_ref" ANY CHECK ("membership_ref" IS NULL OR (typeof("membership_ref")='text' AND length(CAST("membership_ref" AS BLOB))=length("membership_ref") AND length(CAST("membership_ref" AS BLOB)) BETWEEN 1 AND 96 AND "membership_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("membership_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("membership_ref") NOT GLOB 'connector-*' AND lower("membership_ref") NOT GLOB 'tunnel-*' AND lower("membership_ref") NOT GLOB 'workspace-*' AND lower("membership_ref") NOT GLOB 'org-*' AND lower("membership_ref") NOT GLOB 'organization-*' AND lower("membership_ref") NOT GLOB 'user-*')),
  "membership_digest" ANY CHECK ("membership_digest" IS NULL OR (typeof("membership_digest")='text' AND length(CAST("membership_digest" AS BLOB))=64 AND "membership_digest" NOT GLOB '*[^0-9a-f]*')),
  "kind_rank" ANY CHECK ("kind_rank" IS NULL OR (typeof("kind_rank")='integer' AND "kind_rank" BETWEEN 0 AND 9223372036854775807)),
  "value_ref" ANY CHECK ("value_ref" IS NULL OR (typeof("value_ref")='text' AND length(CAST("value_ref" AS BLOB))=length("value_ref") AND length(CAST("value_ref" AS BLOB)) BETWEEN 1 AND 96 AND "value_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("value_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("value_ref") NOT GLOB 'connector-*' AND lower("value_ref") NOT GLOB 'tunnel-*' AND lower("value_ref") NOT GLOB 'workspace-*' AND lower("value_ref") NOT GLOB 'org-*' AND lower("value_ref") NOT GLOB 'organization-*' AND lower("value_ref") NOT GLOB 'user-*')),
  "value_digest" ANY CHECK ("value_digest" IS NULL OR (typeof("value_digest")='text' AND length(CAST("value_digest" AS BLOB))=64 AND "value_digest" NOT GLOB '*[^0-9a-f]*')),
  "value_schema_id" ANY CHECK ("value_schema_id" IS NULL OR (typeof("value_schema_id")='text' AND length(CAST("value_schema_id" AS BLOB)) BETWEEN 1 AND 256)),
  "result_class" ANY NOT NULL CHECK (typeof("result_class")='text' AND length(CAST("result_class" AS BLOB)) BETWEEN 1 AND 256),
  "result_projection_digest" ANY NOT NULL CHECK (typeof("result_projection_digest")='text' AND length(CAST("result_projection_digest" AS BLOB))=64 AND "result_projection_digest" NOT GLOB '*[^0-9a-f]*'),
  "admission_graph_digest" ANY NOT NULL CHECK (typeof("admission_graph_digest")='text' AND length(CAST("admission_graph_digest" AS BLOB))=64 AND "admission_graph_digest" NOT GLOB '*[^0-9a-f]*'),
  "outcome" ANY NOT NULL CHECK (typeof("outcome")='text' AND length(CAST("outcome" AS BLOB)) BETWEEN 1 AND 256),
  "committed_at" ANY NOT NULL CHECK (typeof("committed_at")='text' AND length(CAST("committed_at" AS BLOB))=20 AND length("committed_at")=20 AND "committed_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("committed_at",1,4) BETWEEN '0001' AND '9999' AND substr("committed_at",6,2) BETWEEN '01' AND '12' AND substr("committed_at",9,2) BETWEEN '01' AND '31' AND substr("committed_at",12,2) BETWEEN '00' AND '23' AND substr("committed_at",15,2) BETWEEN '00' AND '59' AND substr("committed_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"committed_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"committed_at")="committed_at"),
  "receipt_digest" ANY NOT NULL CHECK (typeof("receipt_digest")='text' AND length(CAST("receipt_digest" AS BLOB))=64 AND "receipt_digest" NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY (mutation_ref),
  UNIQUE (receipt_digest),
  UNIQUE (membership_ref),
  CHECK (mutation_family IN ('establish_rw0_phase','admit_rw0_evidence')),
  CHECK (outcome='committed'),
  CHECK ((mutation_family='establish_rw0_phase' AND membership_ref IS NULL AND membership_digest IS NULL AND kind_rank IS NULL AND value_ref IS NULL AND value_digest IS NULL AND value_schema_id IS NULL) OR (mutation_family='admit_rw0_evidence' AND membership_ref IS NOT NULL AND membership_digest IS NOT NULL AND kind_rank BETWEEN 1 AND 15 AND value_ref IS NOT NULL AND value_digest IS NOT NULL AND value_schema_id IS NOT NULL)),
  FOREIGN KEY (phase_basis_ref, phase_basis_digest) REFERENCES rw0_phase_instances (phase_basis_ref, phase_basis_digest) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY (phase_basis_ref, membership_ref, membership_digest, kind_rank, value_ref, value_digest, value_schema_id) REFERENCES rw0_evidence_memberships (phase_basis_ref, membership_ref, membership_digest, kind_rank, value_ref, value_digest, value_schema_id) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

